chapter.example:
//! Adds two integers.
//! @param left
//! @param right
//!   The values to add.
//! @returns
//!   The sum of the two values.
int add(int left, int right)
{
  return left + right;
}

subsection.example:
//! - I love you, said Danny.
//!
//! - You have no right to come here after what you did to
//! my little dog, screamed Penny in despair.

//! @decl int dist(int x, int y)
//!   Calculates the distance.
//! @param x
//! @param y
//!   The coordinates of the vector.

subsection.p:
Above, the two @param's x and y are grouped together and share the
same docstring: "The coordinates of the vector.". It is an error to
try to group together different keywords:

subsection.example:
//!   Error, can't group @note and @param:
//! @param x
//! @note
//!   Don't use this function. At all. Ever.

/*! yadda yadda
 *! yadda yadda yadda
 */

/*! @module Foo
 *!   ... doc for the Foo module ...
 *!           ...                 */

  /*! @decl int a()
   *!   ... doc for the method Foo.a() ...
   *!    ....                      */

  /*! @class Bar
   *!   ... doc for the class Foo.Bar  ...
   *!           ...                 */

    /*! @decl mapping(string:string) userprefs()
     *!   ... doc for the method Foo.Bar->userprefs() ...
     *!           ...                 */

    /*! @decl int a
     *! @decl int b
     *!   ... doc for the variables Foo.Bar->a and Foo.Bar->b ...
     *!      ...                      */

  /*! @endclass */

/*! @endmodule */

//! Doc for alpha
int alpha()
{
  return 4711;
}

protected int undocumented;

//! Error! This doc block has no destination!

int beta;
//! Doc for beta

//! Doc for gamma, delta, and epsilon
int gamma, delta;
float epsilon;

//! Error here!
int zeta;
//! ambiguous which doc to associate with zeta.

int eta;
//! Error here too! ambiguous which variable is documented.
int theta;

//! Doc for two methods. This is so UGLY! We strongly recommend
//! using the decl keywords instead to accomplish this effect.
int methodOne()
{
  ...
}
int methodTwo()
{
  ...
}

//! However, it can be useful sometimes, for really short methods:
int very_short() { return 4711; }
int even_shorter() { return 0; }

//! Doc for the class
class CheeseMaker
{
  //! You can even document inherits!
  inherit Earth : earth;

  //! Doc for CheeseMaker->a()
  int a()
  {
    ...
  }

  void create(string s) { ... }
}

class a()
{
  //! @decl foo
  //!    ... doc for foo ...
}

class Roy
//! Documentation for Roy
{
  ....
}

int un_randomize(int x)
//! This function takes a random number, and transforms it into
//! a predictable number.
{
  return x = 4711;
}

//! @decl int a(int x)
//! @decl int b(int x)
//! 	Here is some doc for these functions....

//! Here is some doc for these functions....
int a(int x)
{
   .....
}
int b(int x)
{
   .....
}

//! @decl float cube(float x)
//! @decl int cube(int x)
//! 	Gives x**3.
//! @param x
//! 	The number to cube.
int|float cube(int|float x)
{
   ....
}

subsection.p:
It a portion of the code is unextractable because it contains too much
preprocessor macros and stuff, you can make the extractor skip it by using
@ignore:

subsection.example:
//! @ignore

HERE_ARE_SOME_STRANGE_THINGS
#ifdef A
A
#endif

//! @endignore

//! @ignore
class C {
//! @endignore

  //! To the parser, this function appears to be on the top level
  int f() { ... }

//! @ignore
}
//! @endignore

/*! @module Parser
 *! @module XML */

/*! ... some autodoc comments ... */

/*! @endmodule Parser
 *! @endmodule XML */

/*! @module Legacy
 *! @alias Canonical
 */
/*! @decl int old_run(int value)
 *! @alias Canonical.run()
 */
/*! @endmodule */

//! Two counters.
int a;
int b;

//! @mapping
//!   @member int "ip"
//!     The numeric address.
//!   @member float "latitude"
//!   @member float "longitude"
//!     The coordinates.
//! @endmapping

subsection.p:
Use separate paragraphs for paragraph breaks. Source comments should
 normally use AutoDoc markup such as @i{...@} and
 @expr{...@}, rather than injecting presentation XML through
 @xml{...@}. A table, type description or other block belongs in
 the appropriate documentation-text container, not inside a declaration's
 type metadata merely because its element name is the same.
